package com.example.livevoiceagent.util

import android.icu.text.Transliterator
import android.os.Build

/**
 * Ensures all real-time speech transcripts (especially OpenAI's server-side ASR `input_transcript.delta`,
 * which often defaults to Simplified Chinese for Mandarin speech) are immediately converted to
 * Traditional Chinese (繁體中文).
