object TraditionalChineseConverter {

    private val icuTransliterator: Transliterator? by lazy {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            runCatching {
                Transliterator.getInstance("Hans-Hant")
            }.getOrNull()
        } else {
            null
        }
    }

